package com.cg.pixelguardian;
import android.app.*; import android.os.*; import android.content.*; import android.content.pm.*; import android.provider.Settings; import android.widget.*; import android.graphics.Color; import java.util.*;
public class MainActivity extends Activity {
 LinearLayout panel; void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->action.run());panel.addView(b);} void info(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(17);t.setPadding(8,16,8,16);panel.addView(t);} void open(String action){try{startActivity(new Intent(action));}catch(Exception e){toast("Settings unavailable");}} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 public void onCreate(Bundle b){super.onCreate(b);if(Intent.ACTION_VIEW.equals(getIntent().getAction())){String p=getIntent().getStringExtra("package");String c=getIntent().getStringExtra("class");if(p!=null&&c!=null){try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName(p,c)));finish();return;}catch(Exception e){toast("App unavailable");}}}ScrollView scroll=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(24,40,24,24);panel.setBackgroundColor(0xff102331);scroll.addView(panel);setContentView(scroll);info("CG Pixel Guardian 1.0\nSecurity & home screen recovery");info(Build.MODEL+" · Android "+Build.VERSION.RELEASE+"\nSecurity patch: "+Build.VERSION.SECURITY_PATCH);BatteryManager bm=getSystemService(BatteryManager.class);info("Battery: "+bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)+"%\nAvailable storage: "+new StatFs(getFilesDir().getPath()).getAvailableBytes()/1073741824L+" GB");button("Find apps and create shortcuts",()->apps());button("Default home app",()->open(Settings.ACTION_HOME_SETTINGS));button("Installed apps",()->open(Settings.ACTION_APPLICATION_SETTINGS));button("Security settings",()->open(Settings.ACTION_SECURITY_SETTINGS));button("Privacy settings",()->open(Settings.ACTION_PRIVACY_SETTINGS));button("System updates",()->open(Settings.ACTION_SYSTEM_UPDATE_SETTINGS));button("Storage settings",()->open(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button("Battery settings",()->open(Settings.ACTION_BATTERY_SAVER_SETTINGS));info("For malware scanning, open Google Play Store > profile > Play Protect > Scan. Guardian does not scan for viruses or change system settings automatically.");}
 void apps(){Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> list=getPackageManager().queryIntentActivities(q,0);list.sort(new ResolveInfo.DisplayNameComparator(getPackageManager()));String[] names=new String[list.size()];for(int i=0;i<names.length;i++)names[i]=list.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Choose a launchable app").setItems(names,(d,i)->pin(list.get(i),names[i])).show();}
 void pin(ResolveInfo r,String name){try{ShortcutManager m=getSystemService(ShortcutManager.class);if(!m.isRequestPinShortcutSupported()){toast("Launcher does not support shortcuts");return;}Intent launch=new Intent(this,MainActivity.class).setAction(Intent.ACTION_VIEW).putExtra("package",r.activityInfo.packageName).putExtra("class",r.activityInfo.name);ShortcutInfo s=new ShortcutInfo.Builder(this,"app-"+r.activityInfo.packageName+"-"+r.activityInfo.name).setShortLabel(name).setIntent(launch).build();toast(m.requestPinShortcut(s,null)?"Confirm shortcut on your home screen":"Shortcut request declined");}catch(Exception e){toast("Shortcut unavailable for this app");}}
}